import{_ as t,o,c as a,a3 as s}from"./chunks/framework.D8n1j12q.js";const m=JSON.parse('{"title":"Snapshots","description":"","frontmatter":{},"headers":[],"relativePath":"developers/commands/snapshots.md","filePath":"developers/commands/snapshots.md"}'),d={name:"developers/commands/snapshots.md"};function n(c,e,r,p,h,l){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="snapshots" tabindex="-1">Snapshots <a class="header-anchor" href="#snapshots" aria-label="Permalink to &quot;Snapshots&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32 --loopback repl</span></span>
<span class="line"><span>s32&gt; snapshot store knobs next Verse</span></span>
<span class="line"><span>s32&gt; snapshot store knobs next Chorus</span></span>
<span class="line"><span>s32&gt; snapshot list knobs</span></span>
<span class="line"><span>s32&gt; snapshot recall knobs 0</span></span>
<span class="line"><span>s32&gt; snapshot bank set knobs 1bar 1/4</span></span></code></pre></div><p><code>PART</code> is the bank: <code>knobs</code>, <code>lfos</code>, or <code>rack0</code>…<code>rack7</code>. <code>SLOT</code> is <code>0</code>–<code>31</code>. See <a href="/versions/cli/v1.3.44/snapshots/">Snapshots</a> for how banks work on the S32.</p><h2 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>snapshot list [PART]</code></td><td>Names, which slots are full, and the active one. Default <code>knobs</code></td></tr><tr><td><code>snapshot store PART [SLOT|next] [NAME]</code></td><td>Takes the current sound into a slot. A rack bank with no devices answers <code>BadRequest</code>; <code>Busy</code> during a fade</td></tr><tr><td><code>snapshot recall PART SLOT</code></td><td>Recalls a slot</td></tr><tr><td><code>snapshot delete PART SLOT</code></td><td>Empties a slot. <code>Busy</code> during a fade</td></tr><tr><td><code>snapshot rename PART SLOT NAME</code></td><td>Renames without taking again</td></tr><tr><td><code>snapshot copy|swap|move PART SRC DEST</code></td><td><code>Busy</code> during a fade. An empty source answers <code>NotFound</code></td></tr></tbody></table><h2 id="bank-settings" tabindex="-1">Bank settings <a class="header-anchor" href="#bank-settings" aria-label="Permalink to &quot;Bank settings&quot;">​</a></h2><p><code>snapshot bank get PART</code> and <code>snapshot bank set PART SYNC FADE</code>.</p><table tabindex="0"><thead><tr><th></th><th>Values</th></tr></thead><tbody><tr><td><code>SYNC</code></td><td><code>immediate</code>, <code>1bar</code>, <code>2bars</code>, <code>3bars</code>, <code>4bars</code></td></tr><tr><td><code>FADE</code></td><td><code>off</code>, <code>1/16</code>, <code>1/8</code>, <code>1/4</code>, <code>1/2</code>, <code>1bar</code>, <code>2bars</code>, <code>4bars</code></td></tr></tbody></table><h2 id="in-snapshot" tabindex="-1">IN SNAPSHOT <a class="header-anchor" href="#in-snapshot" aria-label="Permalink to &quot;IN SNAPSHOT&quot;">​</a></h2><p>Each macro, each whole LFO and each whole device has an IN SNAPSHOT switch. So does each parameter. Recall, fade and morph move a parameter only when both its switch and its owner&#39;s switch are on. A take still stores everything. Recall doesn&#39;t change the switches.</p><table tabindex="0"><thead><tr><th>Command</th><th>Switch</th></tr></thead><tbody><tr><td><code>snapshot flags get|set device RACK DEV PARAM [on|off] [yes|no]</code></td><td>One device parameter: IN SNAPSHOT (<code>on</code>/<code>off</code>) and ALLOW MORPH (<code>yes</code>/<code>no</code>)</td></tr><tr><td><code>snapshot flags get|set lfo s32|cv16 INDEX PARAM [on|off] [yes|no]</code></td><td>The same for one LFO parameter</td></tr><tr><td><code>snapshot parent get|set device RACK DEV [on|off]</code></td><td>A whole device</td></tr><tr><td><code>snapshot parent get|set lfo s32|cv16 INDEX [on|off]</code></td><td>A whole LFO</td></tr><tr><td><code>macro set KNOB MACRO in=on|off</code></td><td>One macro</td></tr></tbody></table><h2 id="morph" tabindex="-1">Morph <a class="header-anchor" href="#morph" aria-label="Permalink to &quot;Morph&quot;">​</a></h2><p><code>snapshot morph get|amount|clear PART …</code> fades live toward the active slot. Amount runs <code>0</code>–<code>16383</code>. Above <code>0</code> it starts from what is playing now. <code>0</code> ends a running morph. <code>clear</code> drops it. While a recall fade is running the answer is <code>Busy</code>. See <a href="/versions/cli/v1.3.44/snapshots/morph">Morph</a>.</p><p>In a fresh <code>s32 --loopback repl</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; snapshot store knobs next Verse</span></span>
<span class="line"><span>s32&gt; snapshot morph amount knobs 8192</span></span>
<span class="line"><span>morph amount part=knobs 8192</span></span>
<span class="line"><span>s32&gt; snapshot morph get knobs</span></span>
<span class="line"><span>part=knobs pinA=- pinB=0 morphing=1 amount=8192</span></span>
<span class="line"><span>s32&gt; snapshot morph amount knobs 0</span></span>
<span class="line"><span>morph amount part=knobs 0</span></span>
<span class="line"><span>s32&gt; snapshot morph get knobs</span></span>
<span class="line"><span>part=knobs pinA=- pinB=- morphing=0 amount=0</span></span></code></pre></div><h2 id="arrange" tabindex="-1">Arrange <a class="header-anchor" href="#arrange" aria-label="Permalink to &quot;Arrange&quot;">​</a></h2><p><a href="/versions/cli/v1.3.44/snapshots/lanes">Arrange</a> plays slots as a song: up to 256 rows, one column per bank.</p><p><code>snapshot arrange get</code> prints <code>repeat</code>, <code>rate</code>, <code>length</code>, the playing row (<code>song-row</code>), the armed <strong>QUEUE</strong> (<code>drop-row</code>, <code>none</code> when off), then each column.</p><p><code>snapshot arrange set</code> changes only the keys you name:</p><table tabindex="0"><thead><tr><th>Key</th><th>Values</th></tr></thead><tbody><tr><td><code>repeat</code></td><td><code>loop</code> or <code>once</code></td></tr><tr><td><code>rate</code></td><td>Bars per row, <code>1</code>–<code>128</code></td></tr><tr><td><code>length</code></td><td>Rows, <code>4</code>–<code>256</code></td></tr><tr><td><code>knobs</code>, <code>lfos</code>, <code>rack0</code>…</td><td>Slots and <code>rest</code>, comma-separated. A short list fills the rest of the column with <code>rest</code></td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; snapshot arrange set repeat=once rate=4 knobs=0,1,0,1 lfos=0,rest,3</span></span></code></pre></div><p>A new project starts with <strong>ARRANGE</strong> off. <code>snapshot arrange set</code> writes the song, not that switch: turn <strong>ARRANGE</strong> on in the pencil tab on the panel, or the playhead stays parked and <code>jump</code> / <code>queue</code> do nothing.</p><p><code>snapshot sequence get PART</code> and <code>snapshot sequence set PART rate=… [steps=…]</code> edit one column the same way.</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>snapshot jump ROW</code></td><td>Moves the playhead to <code>ROW</code> (from <code>0</code>)</td></tr><tr><td><code>snapshot queue ROW</code></td><td>Arms a <strong>QUEUE</strong> on <code>ROW</code>. <code>snapshot queue off</code> disarms it</td></tr></tbody></table><h2 id="mapping" tabindex="-1">Mapping <a class="header-anchor" href="#mapping" aria-label="Permalink to &quot;Mapping&quot;">​</a></h2><p><code>macro set</code> and <code>extmap add</code> take <code>target=snapshot-slot</code> or <code>target=morph-amount</code> with <code>part=PART</code>. LFOs can&#39;t target either.</p><ul><li><strong>Snapshot slot:</strong> <code>min=</code> and <code>max=</code> are slots <code>1</code>–<code>32</code>, as on the screen. The knob skips empty slots. A number outside 1–32 on assignment gives the full 1–32.</li><li><strong>Morph amount:</strong> always <code>0</code>–<code>16383</code>. <code>min=</code> and <code>max=</code> are ignored. <code>invert=</code> still works. It always picks up.</li></ul><p>Both turn IN SNAPSHOT off for that macro. To make it a normal macro again, set a new <code>mode=</code> (or <code>rack=</code>, <code>device=</code>, <code>param=</code>, <code>cvParam=</code>) without <code>target=</code>. IN SNAPSHOT comes back on and the range becomes the new mode&#39;s full range:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32&gt; macro set 0 0 target=morph-amount part=knobs</span></span>
<span class="line"><span>s32&gt; macro set 0 0 mode=cc msb=7</span></span>
<span class="line"><span>s32&gt; macro get 0 0</span></span></code></pre></div>`,29)])])}const g=t(d,[["render",n]]);export{m as __pageData,g as default};
